import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Rollen","description":"Die vier Rollen in einem ApptiveGrid-Space und was sie erlauben.","frontmatter":{"title":"Rollen","description":"Die vier Rollen in einem ApptiveGrid-Space und was sie erlauben."},"headers":[],"relativePath":"zusammenarbeit/rollen.md","filePath":"zusammenarbeit/rollen.md","lastUpdated":1786168479000}'),a={name:"zusammenarbeit/rollen.md"};function l(s,e,d,o,c,g){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="rollen" tabindex="-1">Rollen <a class="header-anchor" href="#rollen" aria-label="Permalink to &quot;Rollen&quot;">​</a></h1><p>Jede Person in einem Space hat genau eine <strong>Rolle</strong>. Sie bestimmt, was diese Person tun darf.</p><p>Beim Einladen fragt ApptiveGrid: <em>Der Nutzer kann:</em> — und bietet die Rollen zur Auswahl an.</p><h2 id="die-vier-rollen" tabindex="-1">Die vier Rollen <a class="header-anchor" href="#die-vier-rollen" aria-label="Permalink to &quot;Die vier Rollen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rolle</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Eigentümer</strong></td><td>Die Person, der der Space gehört</td></tr><tr><td><strong>Managen</strong></td><td><em>diesen Space bearbeiten und konfigurieren</em></td></tr><tr><td><strong>Bearbeiten</strong></td><td><em>Inhalte bearbeiten aber nichts konfigurieren</em></td></tr><tr><td><strong>Ansehen</strong></td><td><em>den Space nicht bearbeiten und konfigurieren</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Warum „Managen&quot; und nicht „Administrator&quot;</p><p>Die Rolle heißt in der Oberfläche <strong>Managen</strong>. An einer Stelle — bei den <a href="/integrationen/api-zugangsdaten">API-Zugangsdaten</a> — taucht für eine vergleichbare Stufe der Begriff <em>Admin</em> auf. Gemeint ist eine ähnliche Berechtigungshöhe, es sind aber zwei getrennte Dinge: Rollen gelten für Personen in einem Space, API-Zugangsdaten für den technischen Zugriff auf alle Ihre Spaces.</p></div><h2 id="was-die-rollen-durfen" tabindex="-1">Was die Rollen dürfen <a class="header-anchor" href="#was-die-rollen-durfen" aria-label="Permalink to &quot;Was die Rollen dürfen&quot;">​</a></h2><p>Die Trennlinie verläuft zwischen <strong>Inhalt</strong> und <strong>Struktur</strong>:</p><ul><li><strong>Inhalt</strong> sind die Einträge und ihre Darstellung.</li><li><strong>Struktur</strong> ist alles, was etwas anlegt, löscht oder nach außen freigibt.</li></ul><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Ansehen</th><th style="text-align:center;">Bearbeiten</th><th style="text-align:center;">Managen</th></tr></thead><tbody><tr><td><strong>Lesen</strong> — Grids, Einträge, Felder, Ansichten, Flows, Nutzer</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Einträge anlegen, ändern, löschen</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Ansicht aktualisieren</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Flow-Schritt konfigurieren</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Felder anlegen, ändern, löschen</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Grids anlegen, ändern, löschen</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Ansichten anlegen, löschen, teilen</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Formulare anlegen, ändern, löschen</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Formulare auflisten</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Flows anlegen, löschen; Schritte hinzufügen und entfernen</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Space teilen, Freigaben verwalten</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Space anlegen, ändern, löschen</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Webhooks anlegen, ändern, testen</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>API-Zugangsdaten verwalten</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr></tbody></table><p>Die Rolle <strong>Eigentümer</strong> entspricht <em>Managen</em> und darf zusätzlich Tarif und Sitzplätze anpassen. Die Oberfläche sagt das ausdrücklich: <em>Der Eigentümer kann den Plan anpassen.</em></p><h2 id="drei-punkte-die-uberraschen" tabindex="-1">Drei Punkte, die überraschen <a class="header-anchor" href="#drei-punkte-die-uberraschen" aria-label="Permalink to &quot;Drei Punkte, die überraschen&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Bearbeiten reicht weiter als „nur Einträge&quot;</p><p>Die Kurzbeschreibung <em>Inhalte bearbeiten aber nichts konfigurieren</em> ist etwas zu eng gefasst. Wer <strong>Bearbeiten</strong> hat, darf zusätzlich:</p><ul><li><strong>Ansichten aktualisieren</strong> — eine bestehende Ansicht ändern. Das wirkt für alle, die diese Ansicht nutzen, auch für <a href="/zusammenarbeit/zugriff-beschraenken">geteilte Links</a>.</li><li><strong>Flow-Schritte konfigurieren</strong> — die Einstellungen eines bestehenden Schritts ändern. Neue Schritte anlegen oder löschen darf nur <em>Managen</em>.</li></ul><p>Anlegen, Löschen und Teilen bleiben in beiden Fällen <em>Managen</em> vorbehalten.</p></div><div class="tip custom-block"><p class="custom-block-title">Nicht jede Ansichtsänderung ist dieselbe</p><p>Im Hintergrund werden zwei Arten von Ansichtsänderung unterschieden: eine, die <em>Bearbeiten</em> erlaubt, und eine, die <em>Managen</em> verlangt. Welche Bedienelemente konkret in welche Kategorie fallen, lässt sich von außen nicht sicher sagen.</p><p>Wenn Sie darauf angewiesen sind, dass jemand mit <em>Bearbeiten</em> eine bestimmte Einstellung <strong>nicht</strong> ändern kann, probieren Sie es mit einem Testkonto aus, statt sich auf diese Zuordnung zu verlassen.</p></div><div class="danger custom-block"><p class="custom-block-title">Was das bei Flows bedeutet</p><p>Eine Person mit <strong>Bearbeiten</strong> kann die Konfiguration eines Flow-Schritts ändern — etwa den Empfänger einer E-Mail oder die Zieladresse einer HTTP-Anfrage.</p><p>Der Ablauf bleibt äußerlich gleich, das Ergebnis nicht. Wenn ein Flow sensible Daten verschickt oder <a href="/integrationen/ueberblick">Zugangsdaten eines Fremdsystems</a> enthält, sollten Sie überlegen, wer im Space <em>Bearbeiten</em> hat.</p></div><div class="tip custom-block"><p class="custom-block-title">Lesende sehen die Formularliste nicht</p><p><strong>Formulare auflisten</strong> ist <em>Managen</em> vorbehalten. Ein einzelnes Formular <strong>lesen</strong> darf dagegen jede Rolle.</p><p>Praktisch heißt das: Wer nur <em>Ansehen</em> hat, findet im Navigationsbereich unter einem Grid keine Formulare — kann ein Formular aber öffnen und ausfüllen, wenn er den Link hat. Das ist kein Fehler, sondern so vorgesehen.</p></div><h2 id="wenn-eine-schaltflache-fehlt" tabindex="-1">Wenn eine Schaltfläche fehlt <a class="header-anchor" href="#wenn-eine-schaltflache-fehlt" aria-label="Permalink to &quot;Wenn eine Schaltfläche fehlt&quot;">​</a></h2><p>ApptiveGrid zeigt Funktionen nur an, wenn die Rolle sie erlaubt. Es erscheint <strong>keine Fehlermeldung</strong> und kein ausgegrauter Knopf — die Funktion ist schlicht nicht da.</p><p>Das ist der häufigste Grund für die Frage „Bei mir sieht das anders aus als bei dir&quot;. Prüfen Sie in dem Fall zuerst die Rolle.</p><p>→ <a href="/fehlerbehebung/fehlende-schaltflaechen">Ich sehe eine Schaltfläche nicht</a></p><h2 id="rolle-und-kosten" tabindex="-1">Rolle und Kosten <a class="header-anchor" href="#rolle-und-kosten" aria-label="Permalink to &quot;Rolle und Kosten&quot;">​</a></h2><p>Nur <strong>Ansehen</strong> ist kostenfrei. <strong>Bearbeiten</strong>, <strong>Managen</strong> und <strong>Eigentümer</strong> belegen jeweils einen Sitzplatz.</p><blockquote><p><em>Der Eigentümer kann zusätzliche Plätze für NutzerInnen mit Bearbeitungsrechten erwerben. Leserechte sind kostenfrei.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Im Zweifel mit „Ansehen&quot; beginnen</p><p>Vergeben Sie Bearbeitungsrechte nur, wo sie gebraucht werden. Wer Daten nur lesen soll, kostet nichts — und kann trotzdem Formulare ausfüllen, die auf <em>Jeder aus diesem Space</em> beschränkt sind.</p></div><p>→ <a href="/zusammenarbeit/sitzplaetze">Sitzplätze</a></p><h2 id="rolle-andern" tabindex="-1">Rolle ändern <a class="header-anchor" href="#rolle-andern" aria-label="Permalink to &quot;Rolle ändern&quot;">​</a></h2><p>Öffnen Sie <strong>Space teilen</strong> und ändern Sie die Rolle in der Liste <em>Geteilt mit</em>. Die Änderung greift sofort.</p><p>Ein Herabstufen auf <strong>Ansehen</strong> gibt einen Sitzplatz frei.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/zusammenarbeit/personen-einladen">Personen einladen</a></li><li><a href="/zusammenarbeit/sitzplaetze">Sitzplätze</a></li><li><a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li></ul>',30)])])}const m=t(a,[["render",l]]);export{u as __pageData,m as default};
